const config = {
  "previewFeatures": [],
  "clientVersion": "7.8.0",
  "engineVersion": "3c6e192761c0362d496ed980de936e2f3cebcd3a",
  "activeProvider": "mysql",
  "inlineSchema": "// ------------------------------------------------------\n// Generator & Datasource\n// ------------------------------------------------------\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../generated/prisma\"\n}\n\ndatasource db {\n  provider = \"mysql\"\n}\n\n// ------------------------------------------------------\n// ENUMS\n// ------------------------------------------------------\n\nenum Gender {\n  MALE\n  FEMALE\n}\n\nenum EducationStageType {\n  PRIMARY\n  MIDDLE\n  SECONDARY\n}\n\nenum StudyGroupType {\n  NORMAL\n  ELITE\n  INTENSIVE\n  EVENING\n}\n\nenum DayOfWeek {\n  SATURDAY\n  SUNDAY\n  MONDAY\n  TUESDAY\n  WEDNESDAY\n  THURSDAY\n  FRIDAY\n}\n\nenum PermissionModule {\n  STUDENT\n  TEACHER\n  TEACHING_ASSIGNMENT\n  ENROLLMENT\n  SUBJECT\n  STUDY_GROUP\n  LEVEL\n  EDUCATION_STAGE\n  ACADEMIC_YEAR\n  SCHEDULE\n  SESSION\n  ATTENDANCE\n  INVOICE\n  PAYMENT\n  RECEIPT\n  REPORT\n  USER\n  ROLE\n  SETTINGS\n  CLASSROOM\n  LESSON_SLOT\n  TUITION_FEE\n  SETTLEMENT_POLICY\n  SETTLEMENT\n  TEACHER_PAYMENT\n  /**\n   * النسخُ والاستعادة وإعادة التهيئة — لا تُلحق بـSETTINGS\n   */\n  MAINTENANCE\n}\n\n// ------------------------------------------------------\n// Setting — مفتاح / قيمة\n//\n// هوية المدرسة كانت ثوابت مكتوبة في الواجهة (اسم المركز في الترويسة\n// وشاشة الإقلاع والدخول)، أي أنّ تغيير اسمٍ أو هاتف كان يحتاج مبرمجاً\n// وإعادة بناء. هذا الجدول يجعلها بيانات لا شيفرة.\n//\n// وقيمة نصّية واحدة لكل مفتاح: الأرقام والمنطقيّات تُخزَّن نصّاً وتُفسَّر\n// عند القراءة، فإضافة إعدادٍ جديد لا تمسّ المخطّط إطلاقاً.\n// ------------------------------------------------------\n\nmodel Setting {\n  key       String   @id @map(\"setting_key\") @db.VarChar(64)\n  value     String   @db.Text\n  updatedAt DateTime @updatedAt\n}\n\n// ------------------------------------------------------\n// Academic Year\n// ------------------------------------------------------\n\nmodel AcademicYear {\n  id        String   @id @default(cuid())\n  name      String   @unique\n  startDate DateTime\n  endDate   DateTime\n  isCurrent Boolean  @default(false)\n  isActive  Boolean  @default(true)\n\n  /// عدد الحصص المقرَّرة شهرياً لكل مادة — سقفُ كشف الحضور.\n  ///\n  /// محلُّه السنة لا الإعدادات العامّة: المؤسسة قد تقرّر ثماني حصص في\n  /// 2026/2027 وعشراً في 2027/2028، ولو كان الرقم عامّاً لتبدّلت معه\n  /// كشوفُ السنوات الماضية بأثر رجعي.\n  sessionsPerMonth Int @default(8)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  teachingAssignments TeachingAssignment[]\n  invoices            Invoice[]\n  lessonSlots         LessonSlot[]\n  attendanceSheets    AttendanceSheet[]\n  settlementPolicies  SettlementPolicy[]\n  settlements         Settlement[]\n  tuitionFees         TuitionFee[]\n\n  @@index([isCurrent])\n}\n\n// ------------------------------------------------------\n// Education Stage\n// ------------------------------------------------------\n\nmodel EducationStage {\n  id        String             @id @default(cuid())\n  name      String             @unique\n  type      EducationStageType\n  sortOrder Int\n  isActive  Boolean            @default(true)\n  createdAt DateTime           @default(now())\n  updatedAt DateTime           @updatedAt\n\n  levels      Level[]\n  tuitionFees TuitionFee[]\n}\n\n// ------------------------------------------------------\n// Level\n// ------------------------------------------------------\n\nmodel Level {\n  id               String   @id @default(cuid())\n  educationStageId String\n  name             String\n  sortOrder        Int\n  isActive         Boolean  @default(true)\n  createdAt        DateTime @default(now())\n  updatedAt        DateTime @updatedAt\n\n  educationStage EducationStage @relation(fields: [educationStageId], references: [id])\n  studyGroups    StudyGroup[]\n  tuitionFees    TuitionFee[]\n  students       Student[]\n\n  @@unique([educationStageId, name])\n  @@index([educationStageId])\n}\n\n// ------------------------------------------------------\n// Study Group\n// ------------------------------------------------------\n\nmodel StudyGroup {\n  id          String         @id @default(cuid())\n  levelId     String\n  name        String\n  type        StudyGroupType @default(NORMAL)\n  maxStudents Int?\n  isActive    Boolean        @default(true)\n  createdAt   DateTime       @default(now())\n  updatedAt   DateTime       @updatedAt\n\n  level               Level                @relation(fields: [levelId], references: [id])\n  teachingAssignments TeachingAssignment[]\n  tuitionFees         TuitionFee[]\n  settlementPolicies  SettlementPolicy[]\n\n  @@unique([levelId, name])\n  @@index([levelId])\n  @@index([type])\n}\n\n// ------------------------------------------------------\n// Subject\n// ------------------------------------------------------\n\nmodel Subject {\n  id          String   @id @default(cuid())\n  name        String   @unique\n  code        String?  @unique\n  description String?\n  color       String?\n  /// صورةُ المادة — مسارٌ من /api/uploads، تُعرض في مربّعها\n  imagePath   String?\n  isActive    Boolean  @default(true)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  teachingAssignments TeachingAssignment[]\n  tuitionFees         TuitionFee[]\n  settlementPolicies  SettlementPolicy[]\n}\n\n// ------------------------------------------------------\n// Classroom\n// ------------------------------------------------------\n\nmodel Classroom {\n  id          String   @id @default(cuid())\n  name        String\n  code        String?  @unique\n  capacity    Int?\n  floor       Int?\n  description String?\n  isActive    Boolean  @default(true)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  schedules Schedule[]\n\n  @@index([name])\n}\n\n// ------------------------------------------------------\n// Lesson Slot\n// الإدارة تتحكم بعدد الحصص وأوقاتها\n//\n// مربوط بالسنة الدراسية عمداً: عدد الحصص سياسةُ مؤسسةٍ تتغيّر\n// (8 حصص في 2026/2027 ثم 10 في 2027/2028)، ولو كانت الحصص\n// عالمية لكان تعديلُ سياسةِ سنةٍ جديدة يعدّل نفس السجلات التي\n// تشير إليها جداولُ السنوات الماضية، فتتبدّل كشوفها التاريخية.\n//\n// الترتيب فريد داخل السنة لا عبر السنوات: لكل سنة حصّتها رقم 1.\n// ------------------------------------------------------\n\nmodel LessonSlot {\n  id             String   @id @default(cuid())\n  academicYearId String\n  /// الأستاذ صاحب الفترة — وفارغُه فترةٌ عامّة للمؤسسة.\n  ///\n  /// في مركز الدعم لا جدولَ موحَّد: كلُّ أستاذٍ يأتي في أوقاته، فقد\n  /// يدرّس اثنان في 08:00 كلٌّ في قاعته. ولذلك صارت الفترة مملوكةً.\n  ///\n  /// ولا يُمنع التداخل الزمني — لا في السنة ولا عند المالك الواحد.\n  /// الفترة قالبُ وقتٍ بلا يوم، فأستاذةٌ لها 08:00–10:00 و08:00–09:30\n  /// تدرّس بهما يومين مختلفين. والتعارض الحقيقي يُفحص في `Schedule`:\n  /// أستاذٌ أو فوجٌ أو قاعةٌ في وقتين متداخلين من يومٍ واحد.\n  teacherId      String?\n  name           String\n  order          Int\n  startTime      DateTime @db.Time\n  endTime        DateTime @db.Time\n  isActive       Boolean  @default(true)\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n\n  /// بصمة المالك — yr:<سنة>|tch:<أستاذ أو ->\n  ///\n  /// ضرورةٌ لا زينة: القيد على (academicYearId, teacherId, order) لا\n  /// يمنع تكرار الترتيب بين الفترات العامّة، لأنّ MySQL يعتبر كل NULL\n  /// مميّزاً عن غيره. البصمة النصّية تسدّ الثغرة.\n  ownerKey String @db.VarChar(191)\n\n  academicYear AcademicYear @relation(fields: [academicYearId], references: [id])\n  teacher      Teacher?     @relation(fields: [teacherId], references: [id])\n  schedules    Schedule[]\n\n  @@unique([ownerKey, order])\n  @@index([academicYearId])\n  @@index([teacherId])\n  @@index([isActive])\n}\n\n// ------------------------------------------------------\n// Tuition Fee\n// حقوق الاشتراك الشهرية\n//\n// النطاق أربعةُ حقول اختيارية، والفارغُ منها يعني «أيّاً كان». فصفٌّ\n// بـ educationStageId وحده يسعّر المادة لكل الطور، وصفٌّ بـ studyGroupId\n// يسعّرها لفوجٍ بعينه.\n//\n// وعند تعدّد المطابقات يفوز **أخصُّها**، بأوزان ثنائية:\n//   فوج 8 · مستوى 4 · طور 2 · نوعية 1\n// الثنائيةُ مقصودة: مجموع كل تركيبة فريدٌ لا يساوي غيره، فلا يقع\n// تعادلٌ يحتاج قاعدةَ كسر. الحسابُ في resolveTuitionFee.\n//\n// و `scopeKey` بصمةُ النطاق نصّاً. وجودُه ضرورة لا زينة: MySQL يعتبر\n// كل NULL مميّزاً عن غيره، فقيدٌ فريد على الأعمدة الاختيارية نفسها\n// لا يمنع صفَّين متطابقَي النطاق. البصمةُ تجعل القيد ممكناً.\n//\n// والسعر مربوطٌ بـ **السنة الدراسية** لا بفترة سريان بالتواريخ.\n//\n// كانت هنا [effectiveFrom, effectiveTo)، فكان على المستخدم أن يضبط\n// تاريخاً لا يعنيه ليعمل السعر — ومن أخطأه بقيت الفواتير لا تُولَّد\n// بلا سببٍ ظاهر. والمؤسسة لا تسعّر بالتواريخ أصلاً بل بالسنة: «سعر\n// 2026/2027».\n//\n// وحمايةُ التاريخ المالي لم تكن بالتواريخ يوماً: `Invoice.amount`\n// و`Settlement.tuitionSnapshot` ينسخان السعر لحظة الإصدار، فسبتمبر\n// يبقى بسعره ولو رُفع بعده. النسخُ هو الحارس لا فترةُ السريان.\n// ------------------------------------------------------\n\nmodel TuitionFee {\n  id                 String                    @id @default(cuid())\n  academicYearId     String\n  subjectId          String\n  studyGroupId       String?\n  levelId            String?\n  educationStageId   String?\n  groupType          StudyGroupType?\n  /// بصمة النطاق — yr:Z|sub:X|grp:-|lvl:Y|stg:-|typ:INTENSIVE\n  scopeKey           String                    @db.VarChar(255)\n  amount             Decimal                   @db.Decimal(10, 2)\n  /// معاملةُ الملتحق متأخّراً — تناسبيٌّ افتراضاً\n  lateEnrollmentMode LateEnrollmentBillingMode @default(PRORATED_BY_REMAINING_SESSIONS)\n  isActive           Boolean                   @default(true)\n  createdAt          DateTime                  @default(now())\n  updatedAt          DateTime                  @updatedAt\n\n  academicYear   AcademicYear    @relation(fields: [academicYearId], references: [id])\n  subject        Subject         @relation(fields: [subjectId], references: [id])\n  studyGroup     StudyGroup?     @relation(fields: [studyGroupId], references: [id])\n  level          Level?          @relation(fields: [levelId], references: [id])\n  educationStage EducationStage? @relation(fields: [educationStageId], references: [id])\n\n  // سعرٌ واحد لكل نطاق في كل سنة — والسنة داخل البصمة\n  @@unique([scopeKey])\n  @@index([academicYearId])\n  @@index([subjectId])\n  @@index([studyGroupId])\n  @@index([levelId])\n  @@index([educationStageId])\n  @@index([isActive])\n}\n\n// ------------------------------------------------------\n// Teacher\n// ------------------------------------------------------\n\nmodel Teacher {\n  id             String    @id @default(cuid())\n  firstName      String\n  lastName       String\n  email          String?   @unique\n  phone          String?\n  gender         Gender\n  birthDate      DateTime?\n  hireDate       DateTime\n  address        String?\n  qualification  String?\n  specialization String?\n  salary         Decimal?  @db.Decimal(10, 2)\n  isActive       Boolean   @default(true)\n  createdAt      DateTime  @default(now())\n  updatedAt      DateTime  @updatedAt\n\n  teachingAssignments TeachingAssignment[]\n  settlementPolicies  SettlementPolicy[]\n  settlements         Settlement[]\n  lessonSlots         LessonSlot[]\n  debtShares          TeacherDebtShare[]\n  teacherPayments     TeacherPayment[]\n\n  @@index([lastName])\n}\n\n// ------------------------------------------------------\n// Student\n// ------------------------------------------------------\n\nmodel Student {\n  id               String    @id @default(cuid())\n  /// رقم الطالب في المؤسسة — «2026000147».\n  ///\n  /// أربعُ خاناتٍ لسنة بدء السنة الدراسية التي سُجّل فيها، ثمّ متسلسلٌ\n  /// داخلها. و`id` معرّفٌ داخلي (cuid) لا يُقرأ ولا يُملى ولا يُطبع على\n  /// بطاقة، فهذا هو الرقم الذي يشفّره باركود البطاقة ويراه الموظّف.\n  ///\n  /// والسابقة تُثبَّت **يوم التسجيل** ولا تتغيّر بعده: البطاقة مطبوعةٌ\n  /// في جيب الطالب، ورقمٌ يتبدّل كل سبتمبر يجعل كلّ بطاقةٍ قديمة ورقةً\n  /// لا تُمسح. الجديدُ وحده يأخذ سابقة السنة الجديدة.\n  studentNumber    String    @unique\n  firstName        String\n  lastName         String\n  gender           Gender\n  birthDate        DateTime?\n  /// مسقطُ الرأس — تطلبه شهادة التمدرس، وهو غيرُ `address` (مسكنُه اليوم)\n  birthPlace       String?\n  /// مسار الصورة كما يُرجعه /api/uploads — مثل \"/uploads/1712-93.jpg\"\n  avatar           String?\n  phone            String?\n  parentPhone      String\n  address          String?\n  schoolName       String?\n  emergencyPhone   String?\n  registrationDate DateTime  @default(now())\n\n  /// حقوقُ التسجيل — مبلغٌ يُدفع مرّةً عند التحاقه، غيرُ الحقّ الشهري.\n  ///\n  /// وثلاثةُ حقولٍ لا حقلٌ واحد: الحالةُ وحدها تقول «دُفع» ولا تقول كم\n  /// ولا متى، والوصلُ الذي يُسلَّم للوليّ يحتاجهما.\n  registrationFeePaid   Boolean   @default(false)\n  registrationFeeAmount Decimal?  @db.Decimal(10, 2)\n  registrationFeePaidAt DateTime?\n\n  isActive Boolean @default(true)\n  note     String?\n\n  /// المستوى الدراسي للطالب — «أولى متوسط»، يُختار عند التسجيل.\n  ///\n  /// حقلٌ عليه لا اشتقاقٌ من تسجيلاته: المستوى صفةُ الطالب نفسِه، بينما\n  /// التسجيل يربطه بمادةٍ عند أستاذٍ في فوج. والاشتقاق كان يعطي ثلاث\n  /// إجابات لطالبٍ في ثلاث مواد، ولا يعطي شيئاً لطالبٍ سُجّل للتوّ ولم\n  /// يُسنَد بعد — وهي اللحظة التي تُطبع فيها بطاقته.\n  ///\n  /// والطور لا يُخزَّن معه: `Level.educationStageId` يحمله، وتخزينه\n  /// مرّتين يفتح باب التناقض. النموذج يعرض الطور مرشّحاً للمستويات فقط.\n  ///\n  /// واختياريٌّ لأنّ الصفوف القائمة سبقت الحقل، ولأنّ التسجيل قد يبدأ\n  /// قبل استقرار المستوى — والبطاقة عندها ترتدّ إلى مستوى أفواجه.\n  levelId String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  level       Level?              @relation(fields: [levelId], references: [id])\n  enrollments StudentEnrollment[]\n  documents   StudentDocument[]\n\n  @@index([lastName])\n  @@index([levelId])\n}\n\n// ------------------------------------------------------\n// Student Document — وثائق ملف الطالب\n//\n// وثيقة واحدة لكل نوع لكل طالب (@@unique): إعادة الرفع تستبدل\n// ولا تُراكم، وبذلك يصير سؤال «هل الملف مكتمل؟» قابلاً للحساب\n// بمقارنة الأنواع الموجودة بالأنواع المطلوبة.\n//\n// كتالوج الأنواع في src/modules/student/document.types.ts\n// ------------------------------------------------------\n\nmodel StudentDocument {\n  id           String   @id @default(cuid())\n  studentId    String\n  /// مفتاح النوع — birth_certificate, photo, ...\n  type         String   @db.VarChar(64)\n  /// مسار الملف كما يُرجعه /api/uploads\n  filePath     String\n  /// الاسم الأصلي للعرض والتنزيل\n  fileName     String?\n  note         String?\n  uploadedById String?\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  student    Student @relation(fields: [studentId], references: [id])\n  uploadedBy User?   @relation(\"DocumentUploadedBy\", fields: [uploadedById], references: [id])\n\n  @@unique([studentId, type])\n  @@index([studentId])\n  @@index([type])\n}\n\n// ------------------------------------------------------\n// Teaching Assignment\n// أستاذ + مادة + فوج + سنة دراسية\n// ------------------------------------------------------\n\nmodel TeachingAssignment {\n  id             String   @id @default(cuid())\n  teacherId      String\n  subjectId      String\n  studyGroupId   String\n  academicYearId String\n  isActive       Boolean  @default(true)\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n\n  teacher          Teacher             @relation(fields: [teacherId], references: [id])\n  subject          Subject             @relation(fields: [subjectId], references: [id])\n  studyGroup       StudyGroup          @relation(fields: [studyGroupId], references: [id])\n  academicYear     AcademicYear        @relation(fields: [academicYearId], references: [id])\n  schedules        Schedule[]\n  enrollments      StudentEnrollment[]\n  attendanceSheets AttendanceSheet[]\n  settlements      Settlement[]\n\n  @@unique([teacherId, subjectId, studyGroupId, academicYearId])\n  @@index([teacherId])\n  @@index([subjectId])\n  @@index([studyGroupId])\n  @@index([academicYearId])\n}\n\n// ------------------------------------------------------\n// Student Enrollment\n// تسجيل الطالب في مادة معينة\n// ------------------------------------------------------\n\nmodel StudentEnrollment {\n  id                       String    @id @default(cuid())\n  studentId                String\n  teachingAssignmentId     String\n  /// طابعُ إنشاء السجل — لا تاريخُ الالتحاق. لا يُبنى عليه حسابٌ.\n  enrolledAt               DateTime  @default(now())\n  /**\n   * أوّلُ يومٍ صار الطالب فيه عضواً في الفوج — ومنه تُحسب أهليتُه.\n   * **وفارغُه يعني «مؤهَّلٌ من البداية»**، وهو ما يجعل هذه الإضافة بلا\n   * أثرٍ رجعيّ: كلُّ تسجيلٍ قائمٍ يبقى مؤهَّلاً لكل حصةٍ كما كان، ولا\n   * يتغيّر رقمٌ حُسب سابقاً. والتناسب لا يعمل إلّا لمن يُملأ له صراحةً.\n   * وتاريخٌ لا مؤشّرُ حصة: الحصص تُفصل عن كشفٍ وتُضمّ إلى آخر ويُعاد\n   * ترقيمُها، فمؤشّرٌ إليها يكسره أوّلُ إعادة ضمّ — والتاريخ يصمد.\n   */\n  eligibleFrom             DateTime?\n  /**\n   * خبرٌ عن هذا التسجيل يُعرض في عمود «ملاحظات» بالكشف.\n   * ويكتبه النظامُ لا الموظّف: النقلُ يترك أثره هنا — «مُنقَل من\n   * الفوج 1» في الجديد و«نُقل إلى الفوج 2» في القديم — فيفهم الأستاذ\n   * لِمَ ظهر طالبٌ في منتصف كشفه أو لِمَ غاب.\n   * وهي غيرُ `Student.note`: تلك واحدةٌ للطالب في المؤسسة كلِّها،\n   * يكتبها الموظّف وتظهر في كشوف موادّه جميعاً. وهذه تخصّ فوجاً واحداً.\n   */\n  note                     String?   @db.VarChar(255)\n  /**\n   * الإسنادُ الآخر في النقل — مقصدُ زرّ الملاحظة.\n   * في التسجيل الوافد يشير إلى الفوج المغادَر، وفي المغادَر يشير إلى\n   * الوافد. فمن قرأ «مُنقَل من الفوج 1» فتحه بضغطة بدل أن يعيد\n   * اختيار الطور والمستوى والمادة والأستاذ والفوج.\n   */\n  transferPeerAssignmentId String?\n  /**\n   * كشفُ **هذا الفوج** الذي وقع النقل في أثنائه.\n   * به يُعرف أين يُعرض سطرُ المغادِر: من غادر في كشف مارس لا يُعرض في\n   * كشف جانفي إلى آخر السنة.\n   */\n  transferSheetId          String?\n  /**\n   * كشفُ **الفوج الآخر** في شهر النقل — وإليه يذهب زرّ الملاحظة.\n   * وهو غيرُ `transferSheetId`: لو مُرِّر كشفُ هذا الفوج إلى ذاك\n   * لسقط الاختيار (ليس من كشوفه) وفُتح كشفُه الافتراضيّ — شهرٌ لا\n   * صلة له بالنقل. وفارغُه حين لا كشفَ للفوج الآخر في ذلك الشهر،\n   * فيُفتح الفوجُ ويُترك اختيارُ الكشف له.\n   */\n  transferPeerSheetId      String?\n  /**\n   * يومُ النقل — به تُعرف حصصُه من حصص غيره في الكشف.\n   * المغادِرُ مسؤولٌ عمّا وقع **إلى** هذا اليوم، والوافدُ عمّا وقع\n   * **منه**. وبدونه كان سطرُ المغادِر يعدّ حضوراً في حصصٍ تلت رحيله.\n   */\n  transferAt               DateTime?\n  /**\n   * نقلٌ قُرِّر ولم يسرِ بعد — الإسنادُ المقصود.\n   * والتسجيلُ يبقى **نشطاً** معه: الطالب في فوجه القديم إلى آخر حصةٍ\n   * في الكشف الجاري، يُدوَّن حضورُه ويُفوتَر شهرُه كاملاً هناك. وحين\n   * يُنشأ كشفٌ جديد لهذا الإسناد يُنفَّذ النقلُ من نفسه.\n   */\n  pendingTransferToId      String?\n  /**\n   * يومُ القرار — يُعرض في الملاحظة ويصير `transferAt` عند التنفيذ\n   */\n  pendingTransferAt        DateTime?\n  /**\n   * الكشفُ الجاري يومَ القرار — وبه يُعرف متى يسري.\n   * التنفيذُ عند إنشاء كشفٍ **غيره** لهذا الإسناد. ولولا حفظُه لسرى\n   * النقلُ عند أوّل كشفٍ يُنشأ ولو كان الكشفَ نفسه أُعيد إنشاؤه.\n   */\n  pendingTransferSheetId   String?\n  isActive                 Boolean   @default(true)\n\n  student            Student            @relation(fields: [studentId], references: [id])\n  teachingAssignment TeachingAssignment @relation(fields: [teachingAssignmentId], references: [id])\n  invoices           Invoice[]\n  attendances        Attendance[]\n\n  @@unique([studentId, teachingAssignmentId])\n  @@index([studentId])\n  @@index([teachingAssignmentId])\n}\n\n// ------------------------------------------------------\n// Weekly Schedule\n// ------------------------------------------------------\n\nmodel Schedule {\n  id                   String    @id @default(cuid())\n  teachingAssignmentId String\n  classroomId          String?\n  lessonSlotId         String\n  dayOfWeek            DayOfWeek\n  isActive             Boolean   @default(true)\n  createdAt            DateTime  @default(now())\n  updatedAt            DateTime  @updatedAt\n\n  teachingAssignment TeachingAssignment @relation(fields: [teachingAssignmentId], references: [id])\n  classroom          Classroom?         @relation(fields: [classroomId], references: [id])\n  lessonSlot         LessonSlot         @relation(fields: [lessonSlotId], references: [id])\n  sessions           Session[]\n\n  @@unique([teachingAssignmentId, dayOfWeek, lessonSlotId])\n  @@index([lessonSlotId])\n  @@index([classroomId])\n}\n\n// ------------------------------------------------------\n// Session — الحصة الفعلية\n// ------------------------------------------------------\n\nenum SessionStatus {\n  SCHEDULED\n  COMPLETED\n  CANCELLED\n}\n\nmodel Session {\n  id           String        @id @default(cuid())\n  scheduleId   String\n  lessonNumber Int\n  sessionDate  DateTime\n  status       SessionStatus @default(SCHEDULED)\n  note         String?\n  /// الكشف الذي تنتمي إليه — اختياري لأنّ الحصص المولَّدة من الجدول\n  /// الأسبوعي لا تنتمي إلى كشفٍ حتى تُضمّ إليه\n  sheetId      String?\n  createdAt    DateTime      @default(now())\n  updatedAt    DateTime      @updatedAt\n\n  schedule        Schedule         @relation(fields: [scheduleId], references: [id])\n  sheet           AttendanceSheet? @relation(fields: [sheetId], references: [id])\n  attendances     Attendance[]\n  settlementLines SettlementLine[]\n\n  @@unique([scheduleId, lessonNumber])\n  @@index([sessionDate])\n  @@index([sheetId])\n}\n\n// ------------------------------------------------------\n// Attendance Sheet — كشف الحضور\n//\n// الكشف كان يُشتقّ من نافذة تواريخ: «حصص سبتمبر» ثم ما امتدّ إليه.\n// وكان ذلك يورث تضارباً لا مخرج منه — حصةٌ في مطلع الشهر التالي: أهي\n// ذيلُ هذا الكشف أم مطلعُ الذي يليه؟ والجواب لا يوجد في التقويم لأنّ\n// السؤال ليس تقويمياً: الكشف وحدةٌ إدارية تقررها المؤسسة، وورقتُها\n// الأصلية تحمل «الشهر: 6» لا «فيفري».\n//\n// فصار الكشف كياناً يملك حصصه صراحةً. لا نافذة ولا تخمين: العمود في\n// هذا الكشف لأنّ أحداً وضعه فيه.\n//\n// `sessionCount` منسوخٌ عن سياسة السنة لحظة الإنشاء لا مقروءاً منها —\n// فتغييرُ السياسة لاحقاً لا يُعيد رسم كشوفٍ أُغلقت.\n// ------------------------------------------------------\n\nmodel AttendanceSheet {\n  id                   String   @id @default(cuid())\n  /// رمزُ الورقة — ثلاث عشرة خانة يشفّرها الباركود المطبوع عليها\n  code                 String   @unique\n  teachingAssignmentId String\n  academicYearId       String\n  /// ترتيبه ضمن الإسناد — يُعرض «الشهر رقم 1» ما لم تُكتب تسمية\n  number               Int\n  /// تسمية حرّة تُغني عن الرقم\n  label                String?\n  /// عدد الأعمدة — منسوخ عن سياسة السنة عند الإنشاء\n  sessionCount         Int\n  note                 String?\n  createdAt            DateTime @default(now())\n  updatedAt            DateTime @updatedAt\n\n  teachingAssignment TeachingAssignment @relation(fields: [teachingAssignmentId], references: [id])\n  academicYear       AcademicYear       @relation(fields: [academicYearId], references: [id])\n  sessions           Session[]\n  settlements        Settlement[]\n  invoices           Invoice[]\n\n  @@unique([teachingAssignmentId, number])\n  @@index([teachingAssignmentId])\n  @@index([academicYearId])\n}\n\n// ------------------------------------------------------\n// Attendance\n// ------------------------------------------------------\n\nenum AttendanceStatus {\n  PRESENT\n  ABSENT\n  LATE\n  EXCUSED\n}\n\nmodel Attendance {\n  id                  String           @id @default(cuid())\n  studentEnrollmentId String\n  sessionId           String\n  status              AttendanceStatus @default(PRESENT)\n  note                String?\n  createdAt           DateTime         @default(now())\n  updatedAt           DateTime         @updatedAt\n\n  studentEnrollment StudentEnrollment @relation(fields: [studentEnrollmentId], references: [id])\n  session           Session           @relation(fields: [sessionId], references: [id])\n\n  @@unique([studentEnrollmentId, sessionId])\n  @@index([sessionId])\n  @@index([studentEnrollmentId])\n}\n\n// ------------------------------------------------------\n// User\n// ------------------------------------------------------\n\nmodel User {\n  id          String    @id @default(cuid())\n  username    String    @unique\n  email       String?   @unique\n  password    String\n  firstName   String\n  lastName    String\n  phone       String?\n  avatar      String?\n  /// يُستعمل للأفاتار الافتراضي حين لا صورة — والافتراض MALE لأنّ\n  /// الحسابات القائمة أُنشئت قبل وجود الحقل ولا سبيل لاستنتاج جنسها.\n  gender      Gender    @default(MALE)\n  isActive    Boolean   @default(true)\n  lastLoginAt DateTime?\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n  roleId      String\n\n  role              Role                 @relation(fields: [roleId], references: [id])\n  invoices          Invoice[]            @relation(\"InvoiceCreatedBy\")\n  cancelledInvoices Invoice[]            @relation(\"InvoiceCancelledBy\")\n  payments          Payment[]            @relation(\"PaymentReceivedBy\")\n  cancelledPayments Payment[]            @relation(\"PaymentCancelledBy\")\n  receipts          Receipt[]            @relation(\"ReceiptPrintedBy\")\n  cancelledReceipts Receipt[]            @relation(\"ReceiptCancelledBy\")\n  documents         StudentDocument[]    @relation(\"DocumentUploadedBy\")\n  settlementDocs    SettlementDocument[] @relation(\"SettlementDocUploadedBy\")\n\n  confirmedSettlements     Settlement[]        @relation(\"SettlementConfirmedBy\")\n  paidSettlements          Settlement[]        @relation(\"SettlementPaidBy\")\n  cancelledSettlements     Settlement[]        @relation(\"SettlementCancelledBy\")\n  auditLogs                FinancialAuditLog[] @relation(\"AuditUser\")\n  debtSharesApproved       TeacherDebtShare[]  @relation(\"DebtShareApprovedBy\")\n  teacherPaymentsPaid      TeacherPayment[]    @relation(\"TeacherPaymentPaidBy\")\n  teacherPaymentsCancelled TeacherPayment[]    @relation(\"TeacherPaymentCancelledBy\")\n\n  @@index([roleId])\n}\n\n// ------------------------------------------------------\n// Role\n// ------------------------------------------------------\n\nmodel Role {\n  id          String   @id @default(cuid())\n  name        String   @unique\n  description String?\n  isSystem    Boolean  @default(false)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  users       User[]\n  permissions RolePermission[]\n}\n\n// ------------------------------------------------------\n// Permission\n// ------------------------------------------------------\n\nmodel Permission {\n  id          String           @id @default(cuid())\n  name        String           @unique\n  module      PermissionModule\n  description String?\n  createdAt   DateTime         @default(now())\n  updatedAt   DateTime         @updatedAt\n\n  roles RolePermission[]\n\n  @@index([module])\n}\n\n// ------------------------------------------------------\n// Role Permission\n// ------------------------------------------------------\n\nmodel RolePermission {\n  id           String @id @default(cuid())\n  roleId       String\n  permissionId String\n\n  role       Role       @relation(fields: [roleId], references: [id])\n  permission Permission @relation(fields: [permissionId], references: [id])\n\n  @@unique([roleId, permissionId])\n  @@index([roleId])\n  @@index([permissionId])\n}\n\n// ------------------------------------------------------\n// Invoice — الاستحقاق الشهري للطالب (StudentMonthlyFee)\n//\n// صفٌّ واحد لكل (طالب + مادة + شهر): الطالب المسجَّل في ثلاث مواد\n// له ثلاثة صفوف مستقلة في سبتمبر، يُدفع كلٌّ منها على حدة.\n// القيد @@unique([studentEnrollmentId, month, year]) هو ما يجعل\n// توليد الشهر Idempotent: الضغط على Generate مرتين لا يُكرّر شيئاً.\n//\n// السعر يُنسخ من TuitionFee لحظةَ التوليد إلى amount، فتغييرُ\n// التسعيرة لاحقاً لا يمسّ أشهراً مضت.\n//\n// IMPORTANT — حقول مشتقة:\n//   total     = amount - discount         → يُحسب في service layer\n//   remaining = total - SUM(paidAmount)   → يُحدَّث atomically مع PaymentInvoice\n// ------------------------------------------------------\n\nenum InvoiceStatus {\n  PENDING\n  PARTIAL\n  PAID\n  CANCELLED\n}\n\nmodel Invoice {\n  id                  String        @id @default(cuid())\n  invoiceNumber       String        @unique\n  studentEnrollmentId String\n  academicYearId      String\n  month               Int\n  year                Int\n  amount              Decimal       @db.Decimal(10, 2)\n  /// لقطاتُ التناسب — تشرح كيف خرج المبلغ.\n  ///\n  /// وفارغُها يعني «شهراً كاملاً»، فالفواتير المنشأة قبل هذه الإضافة\n  /// تبقى على معناها بلا تعديل صفٍّ واحد.\n  approvedSessions    Int?\n  eligibleSessions    Int?\n  sessionRate         Decimal?      @db.Decimal(12, 4)\n  /**\n   * الكشف الذي وُلّدت عنه — إن أمكن تحديدُه بلا لبس.\n   * الفاتورة مفتاحُها (تسجيل + شهر + سنة)، والمؤسسة تفكّر بالكشوف:\n   * «فواتير الكشف 2». والربطُ صريحٌ لا مشتقّ لأنّ الاشتقاق يكذب حين\n   * يمتدّ كشفٌ على شهرين أو يتقاسم شهراً كشفان — فيبقى فارغاً حينها\n   * بدل أن يُخمّن.\n   */\n  attendanceSheetId   String?\n  discount            Decimal       @default(0) @db.Decimal(10, 2)\n  total               Decimal       @db.Decimal(10, 2)\n  remaining           Decimal       @db.Decimal(10, 2)\n  status              InvoiceStatus @default(PENDING)\n  dueDate             DateTime\n  note                String?\n  createdById         String?\n  /// أثر الإلغاء — يبقى السجل ويُوثَّق مَن ألغى ومتى ولماذا\n  cancelledAt         DateTime?\n  cancelledById       String?\n  cancelReason        String?\n  createdAt           DateTime      @default(now())\n  updatedAt           DateTime      @updatedAt\n\n  studentEnrollment StudentEnrollment @relation(fields: [studentEnrollmentId], references: [id])\n  academicYear      AcademicYear      @relation(fields: [academicYearId], references: [id])\n  attendanceSheet   AttendanceSheet?  @relation(fields: [attendanceSheetId], references: [id])\n  createdBy         User?             @relation(\"InvoiceCreatedBy\", fields: [createdById], references: [id])\n  cancelledBy       User?             @relation(\"InvoiceCancelledBy\", fields: [cancelledById], references: [id])\n  paymentInvoices   PaymentInvoice[]\n  debtCollections   DebtCollection[]\n\n  @@unique([studentEnrollmentId, month, year])\n  @@index([status])\n  @@index([month, year])\n  @@index([studentEnrollmentId])\n}\n\n// ------------------------------------------------------\n// Payment\n// ------------------------------------------------------\n\nenum PaymentMethod {\n  CASH\n  CARD\n  BANK_TRANSFER\n}\n\n// الدفعة لا تُحذف — تُلغى، وتبقى توزيعاتها للتدقيق.\n// RULE: كل حساب للمدفوع يستثني الدفعات CANCELLED\n//       (يُطبَّق في service layer)\nenum PaymentStatus {\n  ACTIVE\n  CANCELLED\n}\n\nmodel Payment {\n  id            String        @id @default(cuid())\n  paymentNumber String        @unique\n  amount        Decimal       @db.Decimal(10, 2)\n  paymentMethod PaymentMethod @default(CASH)\n  status        PaymentStatus @default(ACTIVE)\n  paymentDate   DateTime      @default(now())\n  note          String?\n  receivedById  String\n  /// أثر الإلغاء — الدفعة لا تُحذف، وتوزيعاتها تبقى للتدقيق\n  cancelledAt   DateTime?\n  cancelledById String?\n  cancelReason  String?\n  createdAt     DateTime      @default(now())\n  updatedAt     DateTime      @updatedAt\n\n  receivedBy      User             @relation(\"PaymentReceivedBy\", fields: [receivedById], references: [id])\n  cancelledBy     User?            @relation(\"PaymentCancelledBy\", fields: [cancelledById], references: [id])\n  paymentInvoices PaymentInvoice[]\n  debtCollections DebtCollection[]\n  receipt         Receipt?\n\n  @@index([paymentDate])\n  @@index([status])\n}\n\n// ------------------------------------------------------\n// PaymentInvoice — جدول وسيط\n// ------------------------------------------------------\n\nmodel PaymentInvoice {\n  id         String   @id @default(cuid())\n  paymentId  String\n  invoiceId  String\n  paidAmount Decimal  @db.Decimal(10, 2)\n  createdAt  DateTime @default(now())\n\n  payment Payment @relation(fields: [paymentId], references: [id])\n  invoice Invoice @relation(fields: [invoiceId], references: [id])\n\n  @@unique([paymentId, invoiceId])\n  @@index([paymentId])\n  @@index([invoiceId])\n}\n\n// ------------------------------------------------------\n// Receipt\n// RULE: printed = true → printedById و printedAt غير null\n//       printed = false → printedById و printedAt = null\n//       تُطبَّق في service layer\n// ------------------------------------------------------\n\nenum ReceiptStatus {\n  ACTIVE\n  CANCELLED\n  REPRINTED\n}\n\nmodel Receipt {\n  id            String        @id @default(cuid())\n  receiptNumber String        @unique\n  paymentId     String        @unique\n  status        ReceiptStatus @default(ACTIVE)\n  printed       Boolean       @default(false)\n  printedAt     DateTime?\n  printedById   String?\n  note          String?\n  /// أثر الإلغاء — الوصل إثباتُ استلام، فلا يُحذف\n  cancelledAt   DateTime?\n  cancelledById String?\n  cancelReason  String?\n  createdAt     DateTime      @default(now())\n\n  payment     Payment @relation(fields: [paymentId], references: [id])\n  printedBy   User?   @relation(\"ReceiptPrintedBy\", fields: [printedById], references: [id])\n  cancelledBy User?   @relation(\"ReceiptCancelledBy\", fields: [cancelledById], references: [id])\n\n  @@index([status])\n}\n\n// ------------------------------------------------------\n// Settlement Policy — سياسة تخليص الأستاذ\n//\n// ما يدفعه الطالب ليس ما يقبضه الأستاذ. لا علاقة ثابتة بينهما إلا\n// ما تقرّره الإدارة هنا، ولذلك لا يوجد في الكود نسبةٌ ولا مبلغ.\n//\n// والحقولُ المشروطة ليست إلزامية كلها: PERCENTAGE تستعمل\n// teacherPercentage وحدها، وPER_SESSION تستعمل amountPerSession\n// وحدها. التحقق من اكتمال حقول الطريقة في service layer، لأن SQL\n// لا يعبّر عن «إلزاميٌّ إذا كان العمود الآخر يساوي كذا».\n// ------------------------------------------------------\n\nenum SettlementMethod {\n  /// نسبة من حقوق الطلبة\n  PERCENTAGE\n  /// مبلغ ثابت لكل طالب\n  PER_STUDENT\n  /// مبلغ ثابت لكل حصة، لا علاقة له بعدد الطلبة\n  PER_SESSION\n  /// نصيب الأستاذ من حصة الطالب الواحدة × الحضور الفعلي\n  PER_ATTENDED_SHARE\n}\n\n/// مَن يُعَدّ طالباً في الحساب.\n///\n/// ENROLLED هو الافتراضي: §6 يُبقي الحقَّ الشهري كاملاً على الطالب\n/// الغائب، فلو خُصم من الأستاذ الذي حضر ودرّس لصار غيابُ الطالب\n/// ربحاً للمؤسسة وحدها. والطرفان يتبعان القاعدة نفسها.\n///\n/// وPAID يجعل الأستاذ يتحمّل تعثّر التحصيل — يُستعمل عن قصد لا سهواً.\nenum SettlementCountBasis {\n  ENROLLED\n  PAID\n  PRESENT\n}\n\nenum RoundingMode {\n  ROUND\n  ROUND_UP\n  ROUND_DOWN\n}\n\nmodel SettlementPolicy {\n  id     String           @id @default(cuid())\n  name   String\n  method SettlementMethod\n\n  teacherPercentage Decimal? @db.Decimal(5, 2)\n  amountPerStudent  Decimal? @db.Decimal(10, 2)\n  amountPerSession  Decimal? @db.Decimal(10, 2)\n\n  countBasis          SettlementCountBasis @default(ENROLLED)\n  /// أين تُنسب حصةُ الأستاذ من دَينٍ حُصِّل متأخّراً\n  debtSettlementBasis DebtSettlementBasis  @default(COLLECTION_PERIOD)\n  /// بأيّ مقياسٍ تُحسب تلك الحصة\n  debtShareBasis      DebtShareBasis       @default(ATTENDED_UNITS)\n  roundingMode        RoundingMode         @default(ROUND)\n  /// عدد المنازل العشرية — التقريب مركزيٌّ هنا لا مبعثرٌ في الحسابات\n  roundingPrecision   Int                  @default(2)\n\n  // نطاق التطبيق — الفارغ يعني «أيّاً كان»، بأوزان: أستاذ 8 · فوج 4 · مادة 2\n  academicYearId String\n  subjectId      String?\n  studyGroupId   String?\n  teacherId      String?\n  /// بصمة النطاق — لنفس سبب scopeKey في TuitionFee\n  scopeKey       String  @db.VarChar(255)\n\n  effectiveFrom DateTime\n  effectiveTo   DateTime?\n  isActive      Boolean   @default(true)\n  note          String?\n  createdAt     DateTime  @default(now())\n  updatedAt     DateTime  @updatedAt\n\n  academicYear AcademicYear @relation(fields: [academicYearId], references: [id])\n  subject      Subject?     @relation(fields: [subjectId], references: [id])\n  studyGroup   StudyGroup?  @relation(fields: [studyGroupId], references: [id])\n  teacher      Teacher?     @relation(fields: [teacherId], references: [id])\n  settlements  Settlement[]\n\n  @@unique([scopeKey, effectiveFrom])\n  @@index([academicYearId])\n  @@index([teacherId])\n  @@index([isActive])\n}\n\n// ------------------------------------------------------\n// Settlement — التخليص الفعلي\n//\n// وحدتُه كشفُ الحضور لا الشهر التقويمي: «الشهر: 4» في الورقة رقمُ\n// كشفٍ، والأستاذ يُخلَّص عن كشفٍ امتلأ بحصصه.\n//\n// وكلُّ ما دخل الحساب منسوخٌ هنا لا مقروءاً من مصدره وقت العرض.\n// فتغييرُ السياسة أو التسعيرة غداً لا يمسّ تخليصاً حُسب اليوم — وهذا\n// شرطٌ غير قابل للتفاوض (§21).\n//\n// و DRAFT وحده يُعاد حسابه؛ CONFIRMED مجمَّد، وتصحيحُه بالإلغاء\n// وإنشاء بديل لا بالتعديل. يُطبَّق في service layer.\n// ------------------------------------------------------\n\n/// كيف يُحتسب حقُّ الشهر لمن التحق بعد بدايته.\n///\n/// محلُّها `TuitionFee` لا `SettlementPolicy`: هذه قاعدةُ **سعرِ طالب**،\n/// وتلك محرّكُ **أجر أستاذ** نطاقُه يشمل المدرّس. ووضعُها هناك يُنتج\n/// سؤالاً بلا جواب — أيُّ سياسةِ أستاذٍ تحكم فاتورةَ طالبٍ يدرس عند ثلاثة؟\nenum LateEnrollmentBillingMode {\n  /// الحقُّ كاملٌ مهما تأخّر الالتحاق\n  FULL_MONTH\n  /// الحقُّ بقدر الحصص التي صار مسؤولاً عنها\n  PRORATED_BY_REMAINING_SESSIONS\n}\n\nenum SettlementStatus {\n  DRAFT\n  CONFIRMED\n  PAID\n  CANCELLED\n}\n\n/// أين تُنسب حصةُ الأستاذ من دَينٍ حُصِّل بعد فترته.\nenum DebtSettlementBasis {\n  /// تعود إلى الفترة التي نشأ فيها الدين — تعديلٌ رجعيّ، لا يصحّ بعد التأكيد\n  ORIGINAL_PERIOD\n  /// تُستحقّ لحظةَ التحصيل وتُدفع مع راتب الفترة التالية — المعتمدة هنا\n  COLLECTION_PERIOD\n  /// تحصيلُ الدين لا يولّد حصةً للأستاذ\n  EXCLUDED\n}\n\n/// بأيّ مقياسٍ تُحسب حصةُ الأستاذ من المبلغ المحصَّل.\n///\n/// المقياسان يفترقان حين يغيب الطالبُ بعضَ الحصص ويسدّد حقَّه كاملاً:\n/// من حضر ثلاثاً من ثمانٍ وسدّد 1500 يُنتج بالمبلغ 1,125 وبالحضور\n/// 421.88. والأوّل يعطي الأستاذ عن ثلاث حصصٍ أجرَ ثمان، والثاني يُبقي\n/// السلسلة كلَّها على مقياس `PER_ATTENDED_SHARE` نفسه فتتصالح المجاميع\n/// مع عمود «غير محصَّل» المعروض في الكشف.\nenum DebtShareBasis {\n  /// حضورُ الطالب في فترته الأصلية × نصيب الوحدة وقتها — الافتراض\n  ATTENDED_UNITS\n  /// المبلغ المحصَّل × نسبة الأستاذ وقتها\n  COLLECTED_AMOUNT\n}\n\n/// مسار حصة الأستاذ من دَينٍ محصَّل.\nenum TeacherDebtShareStatus {\n  /// حُسبت ولم تُعتمد بعد\n  PENDING\n  /// اعتمدتها الإدارة فصارت واجبة الدفع\n  APPROVED\n  /// دُفعت للأستاذ\n  PAID\n  /// أُلغيت — ولا تُحذف\n  CANCELLED\n}\n\n/// حالة دفعةٍ تخرج من المؤسسة إلى الأستاذ.\nenum TeacherPaymentStatus {\n  ACTIVE\n  CANCELLED\n}\n\nmodel Settlement {\n  id               String @id @default(cuid())\n  settlementNumber String @unique\n\n  teachingAssignmentId String\n  attendanceSheetId    String\n  academicYearId       String\n  teacherId            String\n  policyId             String\n\n  /// رقم المحاولة لهذا (إسناد + كشف).\n  ///\n  /// الملغى يبقى ويأخذ البديلُ رقماً تالياً. ولولاه لكان الإلغاء طريقاً\n  /// مسدوداً: قيدُ التفرّد يمنع بديلاً، فيصير «ألغِ واحسب بديلاً»\n  /// نصيحةً لا يمكن اتّباعها.\n  revision Int @default(1)\n\n  // ---- snapshots: السياسة لحظة الحساب ----\n  methodSnapshot            SettlementMethod\n  countBasisSnapshot        SettlementCountBasis\n  roundingModeSnapshot      RoundingMode\n  roundingPrecisionSnapshot Int\n  percentageSnapshot        Decimal?             @db.Decimal(5, 2)\n  perStudentSnapshot        Decimal?             @db.Decimal(10, 2)\n  perSessionSnapshot        Decimal?             @db.Decimal(10, 2)\n\n  // ---- snapshots: المعطيات لحظة الحساب ----\n  /// حقّ الطالب الشهري في هذا الإسناد\n  tuitionSnapshot           Decimal @db.Decimal(10, 2)\n  approvedSessionsSnapshot  Int\n  completedSessionsSnapshot Int\n  studentCountSnapshot      Int\n  paidStudentCountSnapshot  Int\n  /// مجموع (طالب × حصة حضرها) — أساس PER_ATTENDED_SHARE\n  attendedUnitsSnapshot     Int\n  grossTuitionSnapshot      Decimal @db.Decimal(12, 2)\n  collectedSnapshot         Decimal @db.Decimal(12, 2)\n  remainingSnapshot         Decimal @db.Decimal(12, 2)\n\n  /// النتيجة — يحسبها النظام ولا تُقبل من الإدخال إطلاقاً (§18)\n  teacherAmount Decimal @db.Decimal(12, 2)\n\n  status        SettlementStatus @default(DRAFT)\n  computedAt    DateTime         @default(now())\n  confirmedAt   DateTime?\n  confirmedById String?\n  paidAt        DateTime?\n  paidById      String?\n  note          String?\n\n  cancelledAt   DateTime?\n  cancelledById String?\n  cancelReason  String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  teachingAssignment  TeachingAssignment         @relation(fields: [teachingAssignmentId], references: [id])\n  attendanceSheet     AttendanceSheet            @relation(fields: [attendanceSheetId], references: [id])\n  academicYear        AcademicYear               @relation(fields: [academicYearId], references: [id])\n  teacher             Teacher                    @relation(fields: [teacherId], references: [id])\n  policy              SettlementPolicy           @relation(fields: [policyId], references: [id])\n  confirmedBy         User?                      @relation(\"SettlementConfirmedBy\", fields: [confirmedById], references: [id])\n  paidBy              User?                      @relation(\"SettlementPaidBy\", fields: [paidById], references: [id])\n  cancelledBy         User?                      @relation(\"SettlementCancelledBy\", fields: [cancelledById], references: [id])\n  lines               SettlementLine[]\n  documents           SettlementDocument[]\n  snapshot            SettlementSnapshot?\n  debtSharesOrigin    TeacherDebtShare[]         @relation(\"DebtShareOrigin\")\n  debtSharesCollected TeacherDebtShare[]         @relation(\"DebtShareCollection\")\n  teacherAllocations  TeacherPaymentAllocation[]\n\n  // تخليصٌ واحد **غير ملغى** لكل (إسناد + كشف) — والقيد يشمل\n  // revision لأن MySQL لا يعرف الفهارس الجزئية، فشرطُ «غير ملغى»\n  // يُطبَّق في service layer\n  @@unique([teachingAssignmentId, attendanceSheetId, revision])\n  @@index([teacherId])\n  @@index([academicYearId])\n  @@index([status])\n  @@index([attendanceSheetId])\n}\n\n// ------------------------------------------------------\n// Settlement Line — سطرٌ لكل حصة\n//\n// هو نفسه «الكشف التقديري للحصص» (§16) مخزَّناً: الحصة، وعدد\n// الطلبة المحتسبين فيها، وقيمة الوحدة، والمجموع. تخزينُه لا اشتقاقُه\n// عند الطباعة هو ما يجعل الورقة المطبوعة اليوم مطابقةً لنسختها\n// بعد سنة.\n// ------------------------------------------------------\n\nmodel SettlementLine {\n  id              String    @id @default(cuid())\n  settlementId    String\n  sessionId       String?\n  lessonNumber    Int\n  sessionDate     DateTime?\n  /// عدد الطلبة المحتسبين في هذه الحصة وفق countBasis\n  countedStudents Int\n  /// قيمة الوحدة الواحدة — للطالب أو للحصة حسب الطريقة\n  rate            Decimal   @db.Decimal(10, 4)\n  lineTotal       Decimal   @db.Decimal(12, 2)\n\n  createdAt DateTime @default(now())\n\n  settlement Settlement @relation(fields: [settlementId], references: [id], onDelete: Cascade)\n  session    Session?   @relation(fields: [sessionId], references: [id])\n\n  @@index([settlementId])\n  @@index([sessionId])\n}\n\n// ------------------------------------------------------\n// Settlement Document — الورقة الموقَّعة ممسوحةً\n//\n// التخليص يحفظ الحساب، والورقة تحفظ **الإقرار**: إمضاء الأستاذ\n// والإدارة على أنّ المبلغ سُلّم. وهي التي تُخرَج عند النزاع، لا\n// السطر في القاعدة.\n//\n// وعدّة أوراقٍ لا واحدة: الكشف التقديري موقَّعاً، وربّما كشف الحضور\n// معه. والمسار كما يُرجعه /api/uploads — نفس ما تفعله وثائق الطالب.\n// ------------------------------------------------------\n\n/// وجهُ الورقة — الأمامي وحده يكفي، والخلفي حين تُطبع الورقة على وجهين\nmodel SettlementDocument {\n  id           String   @id @default(cuid())\n  settlementId String\n  /// رقمُ الصفحة في الورقة الموقَّعة — واحدٌ فما فوق، بلا حدّ.\n  ///\n  /// كان وجهاً من اثنين، والكشف يطول فيُطبع على ثلاث صفحاتٍ وأربع\n  /// وتعود موقَّعةً كلُّها. فما زاد على الوجهين كان يُستبدل بما قبله.\n  pageNumber   Int      @default(1)\n  /// مسار الملف كما يُرجعه /api/uploads\n  filePath     String\n  /// الاسم الأصلي للعرض والتنزيل\n  fileName     String?\n  note         String?\n  uploadedById String?\n  createdAt    DateTime @default(now())\n\n  settlement Settlement @relation(fields: [settlementId], references: [id], onDelete: Cascade)\n  uploadedBy User?      @relation(\"SettlementDocUploadedBy\", fields: [uploadedById], references: [id])\n\n  @@index([settlementId])\n  @@index([settlementId, pageNumber])\n}\n\n// ------------------------------------------------------\n// Settlement Snapshot — الكشفان مجمَّدين لحظة الدفع\n//\n// التخليص يحفظ لقطة الكشف التقديري في `SettlementLine`. أمّا كشف\n// الحضور اليومي وكشف دفع الحقوق فمعطياتُهما حيّة: حضورٌ يُصحَّح بعد\n// شهر، ودَينٌ يُسدَّد، فتتبدّل الورقة التي وُقّع عليها.\n//\n// فتُجمَّد هنا JSON لحظة إثبات الدفع: ما يُفتح من الأرشيف بعد سنة هو\n// ما رآه الأستاذ حين أمضى، لا ما صارت إليه القاعدة بعده.\n// ------------------------------------------------------\n\nmodel SettlementSnapshot {\n  id           String   @id @default(cuid())\n  settlementId String   @unique\n  /// كشف الحضور اليومي كما كان — حصصُه وحضورُ كلِّ مسجَّل\n  dailySheet   Json\n  /// كشف دفع الحقوق الشهري كما كان — الحصص والحالة المالية\n  monthlyFees  Json\n  createdAt    DateTime @default(now())\n\n  settlement Settlement @relation(fields: [settlementId], references: [id], onDelete: Cascade)\n}\n\n// ------------------------------------------------------\n// Financial Audit Log — أثر التغيير المالي\n//\n// آثارُ الإلغاء الموجودة على الفاتورة والدفعة والوصل تجيب عن «مَن\n// ألغى ولماذا»، لكنها لا تجيب عن «كم كان السعر قبل أن يُرفع». هذا\n// الجدول يحفظ القيمة القديمة والجديدة لكل تغيير مالي.\n//\n// entity نصٌّ لا مفتاح أجنبي عمداً: السجل يبقى بعد حذف موضوعه،\n// وسجلُّ تدقيقٍ يُحذف مع ما يدقّقه لا معنى له.\n// ------------------------------------------------------\n\nenum FinancialAuditAction {\n  CREATE\n  UPDATE\n  CANCEL\n  CONFIRM\n  RECOMPUTE\n}\n\nmodel FinancialAuditLog {\n  id        String               @id @default(cuid())\n  entity    String               @db.VarChar(64)\n  entityId  String\n  action    FinancialAuditAction\n  /// الحقل المتغيّر — فارغ في CREATE و CANCEL\n  field     String?              @db.VarChar(64)\n  oldValue  String?              @db.Text\n  newValue  String?              @db.Text\n  reason    String?\n  userId    String?\n  createdAt DateTime             @default(now())\n\n  user User? @relation(\"AuditUser\", fields: [userId], references: [id])\n\n  @@index([entity, entityId])\n  @@index([userId])\n  @@index([createdAt])\n}\n\n// ======================================================================\n// تحصيل الديون القديمة وحصةُ الأستاذ منها\n//\n// المبدأ الذي تقوم عليه هذه الجداول الأربعة: **المال المحصَّل متأخّراً\n// لا يُعدّل الماضي.** تخليصُ سبتمبر المؤكَّد يبقى 6,750 وإن سُدِّد دينُه\n// في نوفمبر؛ والتصحيح يكون بإنشاء عمليةٍ جديدة تُنسب إلى أصلها لا بمسّ\n// سجلٍّ مضى.\n//\n// والحصة تُخزَّن مستقلّةً وتُدفع مدموجة: الأستاذ يقبض «راتب نوفمبر +\n// حصة دين سبتمبر» دفعةً واحدة، والقاعدةُ تحتفظ بمصدر كلّ دينارٍ منها.\n// ======================================================================\n\n/// تحصيلُ دَينٍ نشأ في فترةٍ سابقة.\n///\n/// مشتقٌّ نظرياً من `PaymentInvoice` + شهر الفاتورة، لكنّه يُصرَّح به\n/// جدولاً لأنّه **الواقعة المحاسبية** التي تتعلّق بها حصةُ الأستاذ.\n/// واستخراجُه باستعلامٍ في كل مرّة يجعل الحصة بلا سندٍ ثابت تُنسب إليه.\nmodel DebtCollection {\n  id String @id @default(cuid())\n\n  /// الفاتورة الأصلية — منها يُعرف الطالب والمادة والفترة\n  invoiceId       String\n  /// الدفعة التي حُصِّل بها\n  paymentId       String\n  /// حصةُ هذه الفاتورة من تلك الدفعة\n  collectedAmount Decimal  @db.Decimal(12, 2)\n  /// شهر الفاتورة وسنتها — منسوخان تسهيلاً للاستعلام والتقارير\n  originalMonth   Int\n  originalYear    Int\n  /// تاريخ القبض — به تُحدَّد فترةُ التحصيل\n  collectedAt     DateTime\n  createdAt       DateTime @default(now())\n\n  invoice       Invoice            @relation(fields: [invoiceId], references: [id])\n  payment       Payment            @relation(fields: [paymentId], references: [id])\n  teacherShares TeacherDebtShare[]\n\n  /// واقعةٌ واحدة لكل (فاتورة + دفعة) — الدفعة الواحدة لا تُحصّل الفاتورة مرّتين\n  @@unique([invoiceId, paymentId])\n  @@index([collectedAt])\n  @@index([originalYear, originalMonth])\n}\n\n/// حصةُ الأستاذ من دَينٍ حُصِّل — مستحقّةٌ ولمّا تُدفع.\n///\n/// ولقطاتُها ضرورة لا زينة: الدينُ نشأ تحت سياسةٍ قد تكون تغيّرت. فمن\n/// حضر تحت نسبة 75% يُحاسَب بها ولو صارت اليوم 80%.\nmodel TeacherDebtShare {\n  id String @id @default(cuid())\n\n  teacherId        String\n  debtCollectionId String\n\n  /// التخليص الذي غطّى الفترة الأصلية — سندُ اللقطات ومانعُ الازدواج\n  originalSettlementId   String?\n  /// التخليص الذي دُفعت معه — يُملأ عند الدمج في راتب فترة التحصيل\n  collectionSettlementId String?\n\n  /// لقطاتُ السياسة الأصلية — لا تُقرأ من `SettlementPolicy` الحالية\n  basisSnapshot      DebtShareBasis\n  percentageSnapshot Decimal        @db.Decimal(5, 2)\n  /// نصيب الوحدة الواحدة وقتها — يُملأ مع ATTENDED_UNITS\n  unitRateSnapshot   Decimal?       @db.Decimal(12, 4)\n  /// وحدات حضور الطالب في فترته الأصلية — يُملأ مع ATTENDED_UNITS\n  attendedUnits      Int?\n\n  /// المبلغ المحصَّل الذي بُنيت عليه\n  collectedAmount Decimal @db.Decimal(12, 2)\n  /// ما يستحقّه الأستاذ — محسوبٌ لا مُدخَل\n  shareAmount     Decimal @db.Decimal(12, 2)\n\n  status TeacherDebtShareStatus @default(PENDING)\n\n  approvedAt   DateTime?\n  approvedById String?\n  paidAt       DateTime?\n  cancelledAt  DateTime?\n  cancelReason String?\n  note         String?\n  createdAt    DateTime  @default(now())\n  updatedAt    DateTime  @updatedAt\n\n  teacher              Teacher                    @relation(fields: [teacherId], references: [id])\n  debtCollection       DebtCollection             @relation(fields: [debtCollectionId], references: [id])\n  originalSettlement   Settlement?                @relation(\"DebtShareOrigin\", fields: [originalSettlementId], references: [id])\n  collectionSettlement Settlement?                @relation(\"DebtShareCollection\", fields: [collectionSettlementId], references: [id])\n  approvedBy           User?                      @relation(\"DebtShareApprovedBy\", fields: [approvedById], references: [id])\n  allocations          TeacherPaymentAllocation[]\n\n  /// حصةٌ واحدة لكل واقعة تحصيل — الحارس البنيوي ضدّ ازدواج الدفع\n  @@unique([debtCollectionId])\n  @@index([teacherId, status])\n  @@index([collectionSettlementId])\n}\n\n/// دفعةٌ تخرج من المؤسسة إلى الأستاذ.\n///\n/// جدولٌ مستقلٌّ عن `Payment` لأنّ اتجاه المال معكوس: ذاك طالبٌ ←\n/// مؤسسة، وهذا مؤسسةٌ ← أستاذ. وخلطُهما يُفسد كلَّ تقرير إيرادٍ ومصروف.\nmodel TeacherPayment {\n  id            String               @id @default(cuid())\n  paymentNumber String               @unique\n  teacherId     String\n  /// المجموع — مشتقٌّ من التخصيصات ومحفوظٌ للاستعلام السريع\n  amount        Decimal              @db.Decimal(12, 2)\n  paymentMethod PaymentMethod        @default(CASH)\n  paymentDate   DateTime\n  reference     String?\n  note          String?\n  status        TeacherPaymentStatus @default(ACTIVE)\n\n  paidById      String?\n  cancelledAt   DateTime?\n  cancelledById String?\n  cancelReason  String?\n  createdAt     DateTime  @default(now())\n  updatedAt     DateTime  @updatedAt\n\n  teacher     Teacher                    @relation(fields: [teacherId], references: [id])\n  paidBy      User?                      @relation(\"TeacherPaymentPaidBy\", fields: [paidById], references: [id])\n  cancelledBy User?                      @relation(\"TeacherPaymentCancelledBy\", fields: [cancelledById], references: [id])\n  allocations TeacherPaymentAllocation[]\n\n  @@index([teacherId])\n  @@index([paymentDate])\n  @@index([status])\n}\n\n/// أين ذهب كلُّ جزءٍ من دفعة الأستاذ.\n///\n/// «دفعتُ له 9,875» جوابٌ لا يكفي. والتخصيص يقول: 8,000 راتب نوفمبر،\n/// و1,125 حصة دين سبتمبر، و750 حصة دين أكتوبر. وهو الفرق بين رقمٍ\n/// يُدافَع عنه ورقمٍ يُصدَّق.\nmodel TeacherPaymentAllocation {\n  id                 String  @id @default(cuid())\n  teacherPaymentId   String\n  /// أحدهما لا كلاهما: تخليصُ فترة أو حصةُ دَين\n  settlementId       String?\n  teacherDebtShareId String?\n  amount             Decimal @db.Decimal(12, 2)\n\n  teacherPayment   TeacherPayment    @relation(fields: [teacherPaymentId], references: [id])\n  settlement       Settlement?       @relation(fields: [settlementId], references: [id])\n  teacherDebtShare TeacherDebtShare? @relation(fields: [teacherDebtShareId], references: [id])\n\n  @@unique([teacherPaymentId, settlementId])\n  @@unique([teacherPaymentId, teacherDebtShareId])\n  @@index([settlementId])\n  @@index([teacherDebtShareId])\n}\n"
}

